  ('Q_20261106_08_04', 'PG', 'Bahasa Inggris SMP 8', 'What do you say when you do not understand the lesson?', 'none', '', '["I am happy", "I don&#x27;t understand", "I am hungry", "Thank you"]'::jsonb, '[]'::jsonb, 'I don&#x27;t understand', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261106_08_05', 'PG', 'Bahasa Inggris SMP 8', 'Your teacher is explaining the lesson. You should ....', 'none', '', '["Sleep", "Talk loudly", "Listen carefully", "Play"]'::jsonb, '[]'::jsonb, 'Listen carefully', 10, 'Sesuai kunci jawaban.'),
